  useEffect(() => {
    const map = mapRef.current;
    if (!map || !readyRef.current) return;
    map.setFilter("quake-selected", ["==", ["get", "id"], selectedId ?? "__none__"]);
  }, [selectedId]);

  useEffect(() => {
