        {hovered && (
          <circle cx={xOf(hovered.time)} cy={BASE - (4 + Math.max(0, Math.min(9, hovered.mag ?? 0)) * ((BASE - TOP - 6) / 9))} r={4} className="timeline-hovermark" />
