/* ————————————————————————————————————————————————
   QuakeScope · survey-paper design system
   ———————————————————————————————————————————————— */
:root {
  --paper: #f3efe6;
  --paper-raised: #fbf9f3;
  --paper-sunken: #eae4d5;
  --ink: #221d15;
  --ink-soft: #5f574a;
  --ink-faint: #8a8172;
  --line: #d9d2c0;
  --line-strong: #b4ab95;
  --accent: #1f6f6b;
  --accent-ink: #14504d;
  --m-minor: #7c8577;
  --m-light: #b1802b;
  --m-moderate: #c14f26;
  --m-major: #8c1d18;
  --alert-green: #2f7d3b;
  --alert-yellow: #8a6a00;
  --alert-orange: #b04e00;
  --alert-red: #b3261e;
  --danger: #a4261f;
  --font-ui: "Inter", system-ui, sans-serif;
  --font-display: "Fraunces", Georgia, serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --shadow: 0 1px 2px rgba(38, 30, 15, 0.08), 0 6px 20px rgba(38, 30, 15, 0.08);
  --radius: 10px;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(31, 111, 107, 0.05), transparent),
    var(--paper);
}
#root { height: 100%; }

button { font: inherit; color: inherit; }
a { color: var(--accent-ink); text-underline-offset: 2px; }
.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 12px; top: -48px;
  z-index: 200;
  background: var(--ink);
  color: var(--paper-raised);
  padding: 10px 16px;
  border-radius: 8px;
  transition: top 120ms ease;
}
.skip-link:focus { top: 12px; }

/* ————— shell ————— */
.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--paper-raised);
  flex-wrap: wrap;
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.wordmark small {
  display: block;
  font-family: var(--font-ui);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.periods {
  display: flex;
  background: var(--paper-sunken);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px;
  gap: 2px;
}
.period-btn {
  border: 0;
  background: transparent;
  border-radius: 999px;
  padding: 7px 14px;
  min-height: 34px;
  cursor: pointer;
  color: var(--ink-soft);
  font-weight: 500;
}
.period-btn:hover { color: var(--ink); }
.period-btn.is-on {
  background: var(--ink);
  color: var(--paper-raised);
}

.topbar-search { flex: 1 1 220px; max-width: 420px; }

.status-cluster {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.status-updated { font-size: 12px; color: var(--ink-soft); }
.status-pill {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid currentColor;
}
.status-offline { color: var(--danger); background: #f7e5e2; }
.status-stale { color: var(--alert-yellow); background: #f4ecd2; }

.btn-refresh {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  background: var(--paper-raised);
  border-radius: 8px;
  padding: 8px 13px;
  min-height: 38px;
  cursor: pointer;
  font-weight: 500;
}
.btn-refresh:hover:not(:disabled) { border-color: var(--ink); }
.btn-refresh:active:not(:disabled) { transform: translateY(1px); }
.btn-refresh:disabled { opacity: 0.55; cursor: default; }
.spin { display: inline-block; animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  font-size: 13px;
}
.banner-warn {
  background: #f4ecd2;
  border-bottom: 1px solid #d8c98e;
  color: #5c4a00;
}

/* ————— layout ————— */
.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(340px, 420px) 1fr;
  min-height: 0;
}

.rail {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-right: 1px solid var(--line-strong);
  background: var(--paper);
}

.stage {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.map-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
}
.map-canvas { position: absolute; inset: 0; }

.map-veil {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(243, 239, 230, 0.72);
  font-family: var(--font-display);
  font-size: 16px;
  color: var(--ink-soft);
  z-index: 5;
}

.map-legend {
  position: absolute;
  left: 12px;
  bottom: 12px;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 12px;
  background: color-mix(in srgb, var(--paper-raised) 92%, transparent);
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 11.5px;
  color: var(--ink-soft);
  box-shadow: var(--shadow);
  flex-wrap: wrap;
}
.legend-title {
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 10px;
  color: var(--ink-faint);
}
.legend-item { display: inline-flex; align-items: center; gap: 5px; }
.dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  display: inline-block;
}
.dot.band-minor { background: var(--m-minor); }
.dot.band-light { background: var(--m-light); }
.dot.band-moderate { background: var(--m-moderate); }
.dot.band-major { background: var(--m-major); }
.dot.dot-deep { background: transparent; border: 2px solid var(--ink-soft); }

.map-tip {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-family: var(--font-ui);
}
.map-tip-mag { font-family: var(--font-mono); font-weight: 600; }
.map-tip-place { font-weight: 500; }
.map-tip-meta { font-size: 11.5px; color: var(--ink-soft); font-family: var(--font-mono); }
.maplibregl-popup-content {
  background: var(--paper-raised);
  color: var(--ink);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: var(--shadow);
  padding: 9px 12px;
  font-size: 13px;
}
.maplibregl-popup-tip { border-top-color: var(--line-strong) !important; }

/* ————— timeline ————— */
.timeline {
  position: relative;
  border-top: 1px solid var(--line-strong);
  background: var(--paper-raised);
  padding: 8px 0 2px;
}
.timeline-head {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding: 0 14px 2px;
}
.timeline-title {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 14px;
}
.timeline-hint { font-size: 12px; color: var(--ink-faint); }
.timeline-window { font-size: 12px; color: var(--accent-ink); font-weight: 600; }
.timeline-clear {
  margin-left: 10px;
  border: 0;
  background: none;
  color: var(--accent-ink);
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
  font-size: 12px;
  padding: 4px;
}
.timeline-svg { display: block; cursor: crosshair; touch-action: pan-y; }
.timeline-hist { fill: var(--paper-sunken); }
.timeline-baseline { stroke: var(--line-strong); }
.timeline-axis-tick { stroke: var(--line-strong); }
.timeline-axis-label {
  fill: var(--ink-faint);
  font-size: 10px;
  font-family: var(--font-mono);
}
.timeline-shade { fill: rgba(243, 239, 230, 0.7); }
.timeline-window-rect {
  fill: rgba(31, 111, 107, 0.07);
  stroke: var(--accent);
  stroke-width: 1.25;
}
.timeline-hovermark {
  fill: none;
  stroke: var(--ink);
  stroke-width: 1.5;
}
.timeline-selmark line { stroke: var(--accent); stroke-width: 1.25; stroke-dasharray: 3 2; }
.timeline-selmark path { fill: var(--accent); }

.timeline-handles { position: absolute; inset: 34px 0 26px; pointer-events: none; }
.timeline-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 22px;
  margin-left: -11px;
  display: grid;
  place-items: center;
  pointer-events: auto;
  color: var(--accent-ink);
  font-size: 11px;
  cursor: ew-resize;
}
.timeline-handle.is-idle { opacity: 0; }
.timeline-handle.is-idle:focus-visible { opacity: 1; }
.timeline-handle span {
  background: var(--paper-raised);
  border: 1px solid var(--accent);
  border-radius: 5px;
  padding: 3px 2px;
  line-height: 1;
}

/* ————— rail: headline, filters, list ————— */
.headline {
  margin: 12px 12px 0;
  text-align: left;
  border: 1px solid var(--line-strong);
  border-left: 4px solid var(--m-moderate);
  background: var(--paper-raised);
  border-radius: var(--radius);
  padding: 11px 13px;
  font-family: var(--font-display);
  font-size: 14.5px;
  line-height: 1.4;
  cursor: pointer;
  box-shadow: var(--shadow);
}
.headline:hover:not(:disabled) { border-color: var(--ink); }
.headline:disabled { cursor: default; }

.filters { padding: 10px 12px 0; }
.filters-bar {
  display: flex;
  align-items: center;
  gap: 8px;
}
.filters-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--paper-raised);
  padding: 8px 12px;
  min-height: 38px;
  cursor: pointer;
  font-weight: 500;
}
.filters-toggle:hover { border-color: var(--ink); }
.chev { display: inline-block; transition: transform 140ms ease; font-size: 11px; }
.chev.is-open { transform: rotate(90deg); }
.filters-count {
  background: var(--accent);
  color: #fff;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  min-width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  padding: 0 5px;
}
.sort-label { margin-left: auto; }
.select {
  font: inherit;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--paper-raised);
  color: var(--ink);
  padding: 8px 10px;
  min-height: 38px;
  cursor: pointer;
}
.btn-reset {
  border: 0;
  background: none;
  color: var(--danger);
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
  padding: 6px;
  font-size: 12.5px;
}

.filters-body {
  margin-top: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper-raised);
  padding: 4px 12px 12px;
}
.filter-group {
  border: 0;
  padding: 8px 0 0;
  margin: 0;
}
.filter-group legend {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-faint);
  padding: 0;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.chip-row, .mag-stops { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  border: 1px solid var(--line-strong);
  background: var(--paper);
  border-radius: 999px;
  padding: 7px 12px;
  min-height: 34px;
  cursor: pointer;
  font-size: 12.5px;
  color: var(--ink-soft);
}
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip.is-on {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--paper-raised);
  font-weight: 600;
}
.chip-alert-green.is-on { background: var(--alert-green); border-color: var(--alert-green); }
.chip-alert-yellow.is-on { background: var(--alert-yellow); border-color: var(--alert-yellow); }
.chip-alert-orange.is-on { background: var(--alert-orange); border-color: var(--alert-orange); }
.chip-alert-red.is-on { background: var(--alert-red); border-color: var(--alert-red); }

.filter-checks { display: grid; gap: 4px; padding-top: 12px; }
.check {
  display: flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
  padding: 5px 0;
  min-height: 32px;
}
.check input {
  width: 17px; height: 17px;
  accent-color: var(--accent);
  cursor: pointer;
}

.hint {
  position: relative;
  border: 1px solid var(--line-strong);
  background: var(--paper);
  color: var(--ink-faint);
  width: 17px; height: 17px;
  border-radius: 50%;
  font-size: 10.5px;
  line-height: 1;
  cursor: help;
  display: inline-grid;
  place-items: center;
  text-transform: none;
  letter-spacing: 0;
  vertical-align: middle;
}
.hint-pop {
  display: none;
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  transform: translateX(-50%);
  width: 240px;
  background: var(--ink);
  color: var(--paper-raised);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: normal;
  text-transform: none;
  line-height: 1.45;
  padding: 9px 11px;
  border-radius: 8px;
  z-index: 60;
  box-shadow: var(--shadow);
  text-align: left;
}
.hint:hover .hint-pop, .hint:focus-visible .hint-pop { display: block; }

.result-count {
  margin: 12px 12px 6px;
  font-size: 12.5px;
  color: var(--ink-soft);
  border-bottom: 1px dashed var(--line-strong);
  padding-bottom: 7px;
}
.result-count strong { font-weight: 600; color: var(--ink); }

/* event list */
.event-scroll {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
  padding: 0 8px;
  scrollbar-width: thin;
}
.event-list {
  list-style: none;
  margin: 0;
  padding: 0;
  position: relative;
}
.event-item {
  position: absolute;
  left: 0; right: 0;
  height: 74px;
  padding: 3px 4px;
}
.event-row {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 11px;
  text-align: left;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: transparent;
  padding: 6px 10px;
  cursor: pointer;
}
.event-row:hover, .event-row.is-hovered {
  background: var(--paper-raised);
  border-color: var(--line);
}
.event-row.is-selected {
  background: var(--paper-raised);
  border-color: var(--accent);
  box-shadow: inset 3px 0 0 var(--accent);
}

.mag-disc {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 13.5px;
  color: #fff;
  border: 2px solid transparent;
}
.mag-disc.band-minor { background: var(--m-minor); }
.mag-disc.band-light { background: var(--m-light); }
.mag-disc.band-moderate { background: var(--m-moderate); }
.mag-disc.band-major { background: var(--m-major); font-size: 15px; }

.event-main { min-width: 0; flex: 1; display: flex; flex-direction: column; gap: 2px; }
.event-place {
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.event-meta { font-size: 11.5px; color: var(--ink-soft); }

.event-tags { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; flex: none; }
.tag {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid var(--line-strong);
  color: var(--ink-soft);
  background: var(--paper-raised);
  white-space: nowrap;
}
.tag-new { color: var(--accent-ink); border-color: var(--accent); background: #e4efee; }
.tag-tsunami { color: #0b4f79; border-color: #0b4f79; background: #e1eef7; }
.tag-alert-green { color: var(--alert-green); border-color: var(--alert-green); background: #e5f1e6; }
.tag-alert-yellow { color: var(--alert-yellow); border-color: var(--alert-yellow); background: #f6efd4; }
.tag-alert-orange { color: var(--alert-orange); border-color: var(--alert-orange); background: #f9e8d8; }
.tag-alert-red { color: var(--alert-red); border-color: var(--alert-red); background: #f9e2e0; }

.rail-foot {
  padding: 10px 14px;
  border-top: 1px solid var(--line);
  font-size: 11px;
  color: var(--ink-faint);
  line-height: 1.5;
}

/* skeleton */
.skeleton-list { padding: 4px 12px; }
.skeleton-row {
  display: flex;
  gap: 11px;
  align-items: center;
  height: 68px;
}
.skeleton-disc, .skeleton-lines span {
  background: linear-gradient(90deg, var(--paper-sunken) 25%, #f1ece0 50%, var(--paper-sunken) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.4s ease infinite;
}
.skeleton-disc { width: 44px; height: 44px; border-radius: 50%; flex: none; }
.skeleton-lines { flex: 1; display: flex; flex-direction: column; gap: 7px; }
.skeleton-lines span { height: 11px; border-radius: 4px; }
.skeleton-lines span:last-child { width: 55%; }
@keyframes shimmer { to { background-position: -200% 0; } }

/* state cards */
.state-card {
  margin: 18px 12px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  padding: 20px 18px;
  background: var(--paper-raised);
}
.state-card h2 {
  font-family: var(--font-display);
  font-size: 17px;
  margin: 0 0 8px;
}
.state-card p { margin: 0 0 10px; color: var(--ink-soft); }
.btn-solid {
  border: 0;
  background: var(--ink);
  color: var(--paper-raised);
  border-radius: 8px;
  padding: 10px 16px;
  min-height: 44px;
  font-weight: 600;
  cursor: pointer;
}
.btn-solid:hover { background: #3a332a; }
.btn-solid:active { transform: translateY(1px); }

.btn-ghost {
  border: 1px solid transparent;
  background: none;
  color: var(--accent-ink);
  cursor: pointer;
  padding: 8px 10px;
  min-height: 38px;
  border-radius: 8px;
  font-weight: 500;
}
.btn-ghost:hover { background: var(--paper-sunken); }

/* ————— detail ————— */
.detail {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px 20px;
  min-height: 0;
}
.detail-top {
  display: flex;
  justify-content: space-between;
  margin: 0 -8px 6px;
}
.detail-head {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 12px;
}
.detail-mag {
  flex: none;
  width: 76px;
  height: 76px;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #fff;
}
.detail-mag.band-minor { background: var(--m-minor); }
.detail-mag.band-light { background: var(--m-light); }
.detail-mag.band-moderate { background: var(--m-moderate); }
.detail-mag.band-major { background: var(--m-major); }
.detail-mag-value { font-size: 24px; font-weight: 600; line-height: 1; }
.detail-mag-label { font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.1em; opacity: 0.9; margin-top: 3px; }

.detail-place {
  font-family: var(--font-display);
  font-size: 21px;
  font-weight: 600;
  line-height: 1.25;
  margin: 2px 0 6px;
  overflow-wrap: anywhere;
}
.detail-when { margin: 0; font-size: 12px; color: var(--ink-soft); }
.detail-utc { color: var(--ink-faint); }

.detail-note {
  border-radius: 8px;
  padding: 9px 12px;
  font-size: 13px;
  font-weight: 500;
  margin: 0 0 10px;
}
.tone-calm { background: #e9ede6; color: #3c4a3a; }
.tone-notable { background: #f6efd4; color: #5c4a00; }
.tone-elevated { background: #f9e2e0; color: var(--alert-red); }

.detail-safety {
  margin: 0 0 10px;
  font-size: 12.5px;
  color: var(--ink-soft);
  border-left: 3px solid var(--alert-red);
  padding-left: 10px;
}

.detail-grid { margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.detail-row { background: var(--paper-raised); padding: 10px 12px; }
.detail-row dt {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-faint);
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}
.detail-row dd { margin: 0; font-size: 13.5px; }
.dd-sub { display: block; font-size: 11.5px; color: var(--ink-soft); margin-top: 3px; }
.dd-missing { color: var(--ink-faint); font-style: italic; }

.detail-usgs {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
  font-weight: 600;
  background: var(--paper-raised);
  border: 1px solid var(--line-strong);
  padding: 10px 14px;
  min-height: 44px;
  border-radius: 8px;
  text-decoration: none;
}
.detail-usgs:hover { border-color: var(--ink); }
.detail-caveat {
  font-size: 11.5px;
  color: var(--ink-faint);
  margin-top: 14px;
  line-height: 1.5;
}

/* ————— search ————— */
.search { position: relative; }
.search-field {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--paper-raised);
  padding: 0 10px;
  min-height: 38px;
}
.search-field:focus-within { border-color: var(--accent); }
.search-icon { color: var(--ink-faint); flex: none; }
.search-input {
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  flex: 1;
  min-width: 0;
  padding: 8px 0;
}
.search-input:focus { outline: none; }
.search-input::placeholder { color: var(--ink-faint); }
.search-clear {
  border: 0;
  background: none;
  font-size: 17px;
  color: var(--ink-faint);
  cursor: pointer;
  padding: 4px 6px;
}
.search-clear:hover { color: var(--ink); }

.search-pop {
  position: absolute;
  top: calc(100% + 6px);
  left: 0; right: 0;
  background: var(--paper-raised);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px 12px;
  z-index: 100;
}
.search-pop-note { margin: 0 0 6px; font-size: 12px; color: var(--ink-soft); }
.search-pop-head {
  margin: 8px 0 4px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.search-hits { list-style: none; margin: 0; padding: 0; }
.search-hit {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: none;
  padding: 8px 8px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12.5px;
  color: var(--ink);
}
.search-hit:hover { background: var(--paper-sunken); }
.search-pop-credit { margin: 8px 0 0; font-size: 10.5px; color: var(--ink-faint); }

/* ————— mobile ————— */
.mobile-switch { display: none; }

@media (max-width: 900px) {
  body { font-size: 15px; }
  .topbar { gap: 10px; padding: 8px 12px; }
  .wordmark { font-size: 17px; }
  .wordmark small { display: none; }
  .topbar-search { order: 4; flex: 1 1 100%; max-width: none; }
  .status-cluster { margin-left: auto; }
  .status-updated { display: none; }

  .layout { grid-template-columns: 1fr; position: relative; }
  .rail {
    display: none;
    border-right: 0;
  }
  .rail.is-mobile-visible { display: flex; }
  .stage.is-mobile-hidden { display: none; }

  .app { height: 100dvh; }
  .mobile-switch {
    display: flex;
    border-top: 1px solid var(--line-strong);
    background: var(--paper-raised);
    padding: 8px 12px calc(8px + env(safe-area-inset-bottom));
    gap: 8px;
  }
  .mobile-switch button {
    flex: 1;
    min-height: 46px;
    border: 1px solid var(--line-strong);
    border-radius: 10px;
    background: var(--paper);
    font-weight: 600;
    cursor: pointer;
  }
  .mobile-switch button.is-on {
    background: var(--ink);
    border-color: var(--ink);
    color: var(--paper-raised);
  }

  .timeline-hint { display: none; }
  .detail-grid { grid-template-columns: 1fr; }
  .map-legend { left: 8px; bottom: 8px; gap: 8px; font-size: 10.5px; }
}

@media (min-width: 1600px) {
  .layout { grid-template-columns: 460px 1fr; }
}

/* ————— reduced motion ————— */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

tool_use_result.content:
/* ————————————————————————————————————————————————
   QuakeScope · survey-paper design system
   ———————————————————————————————————————————————— */
:root {
  --paper: #f3efe6;
  --paper-raised: #fbf9f3;
  --paper-sunken: #eae4d5;
  --ink: #221d15;
  --ink-soft: #5f574a;
  --ink-faint: #8a8172;
  --line: #d9d2c0;
  --line-strong: #b4ab95;
  --accent: #1f6f6b;
  --accent-ink: #14504d;
  --m-minor: #7c8577;
  --m-light: #b1802b;
  --m-moderate: #c14f26;
  --m-major: #8c1d18;
  --alert-green: #2f7d3b;
  --alert-yellow: #8a6a00;
  --alert-orange: #b04e00;
  --alert-red: #b3261e;
  --danger: #a4261f;
  --font-ui: "Inter", system-ui, sans-serif;
  --font-display: "Fraunces", Georgia, serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --shadow: 0 1px 2px rgba(38, 30, 15, 0.08), 0 6px 20px rgba(38, 30, 15, 0.08);
  --radius: 10px;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(31, 111, 107, 0.05), transparent),
    var(--paper);
}
#root { height: 100%; }

button { font: inherit; color: inherit; }
a { color: var(--accent-ink); text-underline-offset: 2px; }
.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 12px; top: -48px;
  z-index: 200;
  background: var(--ink);
  color: var(--paper-raised);
  padding: 10px 16px;
  border-radius: 8px;
  transition: top 120ms ease;
}
.skip-link:focus { top: 12px; }

/* ————— shell ————— */
.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--paper-raised);
  flex-wrap: wrap;
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.wordmark small {
  display: block;
  font-family: var(--font-ui);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.periods {
  display: flex;
  background: var(--paper-sunken);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px;
  gap: 2px;
}
.period-btn {
  border: 0;
  background: transparent;
  border-radius: 999px;
  padding: 7px 14px;
  min-height: 34px;
  cursor: pointer;
  color: var(--ink-soft);
  font-weight: 500;
}
.period-btn:hover { color: var(--ink); }
.period-btn.is-on {
  background: var(--ink);
  color: var(--paper-raised);
}

.topbar-search { flex: 1 1 220px; max-width: 420px; }

.status-cluster {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.status-updated { font-size: 12px; color: var(--ink-soft); }
.status-pill {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid currentColor;
}
.status-offline { color: var(--danger); background: #f7e5e2; }
.status-stale { color: var(--alert-yellow); background: #f4ecd2; }

.btn-refresh {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  background: var(--paper-raised);
  border-radius: 8px;
  padding: 8px 13px;
  min-height: 38px;
  cursor: pointer;
  font-weight: 500;
}
.btn-refresh:hover:not(:disabled) { border-color: var(--ink); }
.btn-refresh:active:not(:disabled) { transform: translateY(1px); }
.btn-refresh:disabled { opacity: 0.55; cursor: default; }
.spin { display: inline-block; animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  font-size: 13px;
}
.banner-warn {
  background: #f4ecd2;
  border-bottom: 1px solid #d8c98e;
  color: #5c4a00;
}

/* ————— layout ————— */
.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(340px, 420px) 1fr;
  min-height: 0;
}

.rail {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-right: 1px solid var(--line-strong);
  background: var(--paper);
}

.stage {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.map-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
}
.map-canvas { position: absolute; inset: 0; }

.map-veil {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(243, 239, 230, 0.72);
  font-family: var(--font-display);
  font-size: 16px;
  color: var(--ink-soft);
  z-index: 5;
}

.map-legend {
  position: absolute;
  left: 12px;
  bottom: 12px;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 12px;
  background: color-mix(in srgb, var(--paper-raised) 92%, transparent);
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 11.5px;
  color: var(--ink-soft);
  box-shadow: var(--shadow);
  flex-wrap: wrap;
}
.legend-title {
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 10px;
  color: var(--ink-faint);
}
.legend-item { display: inline-flex; align-items: center; gap: 5px; }
.dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  display: inline-block;
}
.dot.band-minor { background: var(--m-minor); }
.dot.band-light { background: var(--m-light); }
.dot.band-moderate { background: var(--m-moderate); }
.dot.band-major { background: var(--m-major); }
.dot.dot-deep { background: transparent; border: 2px solid var(--ink-soft); }

.map-tip {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-family: var(--font-ui);
}
.map-tip-mag { font-family: var(--font-mono); font-weight: 600; }
.map-tip-place { font-weight: 500; }
.map-tip-meta { font-size: 11.5px; color: var(--ink-soft); font-family: var(--font-mono); }
.maplibregl-popup-content {
  background: var(--paper-raised);
  color: var(--ink);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: var(--shadow);
  padding: 9px 12px;
  font-size: 13px;
}
