const onKeyDown = useCallback(
  (e: React.KeyboardEvent) => {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
    e.preventDefault();
    const idx = selectedId ? quakes.findIndex((q) => q.id === selectedId) : -1;
    let next = idx;
    if (e.key === "ArrowDown") next = Math.min(quakes.length - 1, idx + 1);
    else if (e.key === "ArrowUp") next = Math.max(0, idx === -1 ? 0 : idx - 1);
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = quakes.length - 1;
    if (next >= 0 && next < quakes.length && next !== idx) onSelect(quakes[next].id);
  },
  [quakes, selectedId, onSelect],
);

