      else if (e.key === "ArrowUp") next = Math.max(0, idx === -1 ? 0 : idx - 1);
      else if (e.key === "Home") next = 0;
      else if (e.key === "End") next = quakes.length - 1;
      if (next >= 0 && next < quakes.length && next !== idx) onSelect(quakes[next].id);
    },
    [quakes, selectedId, onSelect],
  );

  const first = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - OVERSCAN);
  const last = Math.min(quakes.length, Math.ceil((scrollTop + viewport) / ROW_HEIGHT) + OVERSCAN);
