dev-browser --browser chrome --connect http://127.0.0.1:9333 <<'EOF'
const page = await browser.getPage("qs2");
await page.goto("http://localhost:9201");
await page.waitForTimeout(5000);
// Simulate USGS outage, then refresh
await page.route("**earthquake.usgs.gov/**", (route) => route.abort());
await page.getByRole("button", { name: /Refresh/ }).click();
await page.waitForTimeout(2500);
const banner = await page.locator(".banner").innerText().catch(() => "NO BANNER");
const count = await page.locator(".result-count").innerText();
const s = await saveScreenshot(await page.screenshot(), "error-banner.png");
// Full failure on cold load: reload with route still blocked
await page.reload();
await page.waitForTimeout(3000);
const cold = await page.locator(".state-card").innerText().catch(() => "NO CARD");
const s2 = await saveScreenshot(await page.screenshot(), "error-cold.png");
await page.unroute("**earthquake.usgs.gov/**");
console.log(JSON.stringify({ banner, count, cold: cold.slice(0, 220), s, s2 }));
EOF

