tool_use_result.originalFile:
/* ————————————————————————————————————————————————
   QuakeScope · survey-paper design system
   ———————————————————————————————————————————————— */
:root {
  --paper: #f3efe6;
  --paper-raised: #fbf9f3;
  --paper-sunken: #eae4d5;
  --ink: #221d15;
  --ink-soft: #5f574a;
  --ink-faint: #736b5c;
  --line: #d9d2c0;
  --line-strong: #b4ab95;
  --accent: #1f6f6b;
  --accent-ink: #14504d;
  --m-minor: #7c8577;
  --m-light: #b1802b;
  --m-moderate: #c14f26;
  --m-major: #8c1d18;
  --alert-green: #2f7d3b;
  --alert-yellow: #8a6a00;
  --alert-orange: #b04e00;
  --alert-red: #b3261e;
  --danger: #a4261f;
  --font-ui: "Inter", system-ui, sans-serif;
  --font-display: "Fraunces", Georgia, serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --shadow: 0 1px 2px rgba(38, 30, 15, 0.08), 0 6px 20px rgba(38, 30, 15, 0.08);
  --radius: 10px;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(31, 111, 107, 0.05), transparent),
    var(--paper);
}
#root { height: 100%; }

button { font: inherit; color: inherit; }
a { color: var(--accent-ink); text-underline-offset: 2px; }
.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 12px; top: -48px;
  z-index: 200;
  background: var(--ink);
  color: var(--paper-raised);
  padding: 10px 16px;
  border-radius: 8px;
  transition: top 120ms ease;
}
.skip-link:focus { top: 12px; }

/* ————— shell ————— */
.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--paper-raised);
  flex-wrap: wrap;
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.wordmark small {
  display: block;
  font-family: var(--font-ui);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.periods {
  display: flex;
  background: var(--paper-sunken);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px;
  gap: 2px;
}
.period-btn {
  border: 0;
  background: transparent;
  border-radius: 999px;
  padding: 7px 14px;
  min-height: 34px;
  cursor: pointer;
  color: var(--ink-soft);
  font-weight: 500;
}
.period-btn:hover { color: var(--ink); }
.period-btn.is-on {
  background: var(--ink);
  color: var(--paper-raised);
}

.topbar-search { flex: 1 1 220px; max-width: 420px; }

.status-cluster {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.status-updated { font-size: 12px; color: var(--ink-soft); }
.status-pill {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid currentColor;
}
.status-offline { color: var(--danger); background: #f7e5e2; }
.status-stale { color: var(--alert-yellow); background: #f4ecd2; }

.btn-refresh {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  background: var(--paper-raised);
  border-radius: 8px;
  padding: 8px 13px;
  min-height: 38px;
  cursor: pointer;
  font-weight: 500;
}
.btn-refresh:hover:not(:disabled) { border-color: var(--ink); }
.btn-refresh:active:not(:disabled) { transform: translateY(1px); }
.btn-refresh:disabled { opacity: 0.55; cursor: default; }
.spin { display: inline-block; animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  font-size: 13px;
}
.banner-warn {
  background: #f4ecd2;
  border-bottom: 1px solid #d8c98e;
  color: #5c4a00;
}

/* ————— layout ————— */
.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(340px, 420px) 1fr;
  min-height: 0;
}

.rail {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-right: 1px solid var(--line-strong);
  background: var(--paper);
}

.stage {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.map-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
}
.map-canvas { position: absolute; inset: 0; }

.map-fallback {
  display: grid;
  place-content: center;
  gap: 4px;
  text-align: center;
  padding: 24px;
  background: var(--paper-sunken);
  color: var(--ink-soft);
}
.map-fallback p { margin: 0; max-width: 420px; }

.map-veil {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(243, 239, 230, 0.72);
  font-family: var(--font-display);
  font-size: 16px;
  color: var(--ink-soft);
  z-index: 5;
}

.map-legend {
  position: absolute;
  left: 12px;
  bottom: 12px;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 12px;
  background: color-mix(in srgb, var(--paper-raised) 92%, transparent);
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 11.5px;
  color: var(--ink-soft);
  box-shadow: var(--shadow);
  flex-wrap: wrap;
}
.legend-title {
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 10px;
  color: var(--ink-faint);
}
.legend-item { display: inline-flex; align-items: center; gap: 5px; }
.dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  display: inline-block;
}
.dot.band-minor { background: var(--m-minor); }
.dot.band-light { background: var(--m-light); }
.dot.band-moderate { background: var(--m-moderate); }
.dot.band-major { background: var(--m-major); }
.dot.dot-deep { background: transparent; border: 2px solid var(--ink-soft); }

.map-tip {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-family: var(--font-ui);
}
.map-tip-mag { font-family: var(--font-mono); font-weight: 600; }
.map-tip-place { font-weight: 500; }
.map-tip-meta { font-size: 11.5px; color: var(--ink-soft); font-family: var(--font-mono); }
.maplibregl-popup-content {
  background: var(--paper-raised);
  color: var(--ink);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: var(--shadow);
  padding: 9px 12px;
  font-size: 13px;
}
.maplibregl-popup-tip { border-top-color: var(--line-strong) !important; }

/* ————— timeline ————— */
.timeline {
  position: relative;
  border-top: 1px solid var(--line-strong);
  background: var(--paper-raised);
  padding: 8px 0 2px;
}
.timeline-head {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding: 0 14px 2px;
}
.timeline-title {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 14px;
}
.timeline-hint { font-size: 12px; color: var(--ink-faint); }
.timeline-window { font-size: 12px; color: var(--accent-ink); font-weight: 600; }
.timeline-clear {
  margin-left: 10px;
  border: 0;
  background: none;
  color: var(--accent-ink);
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
  font-size: 12px;
  padding: 4px;
}
.timeline-svg { display: block; cursor: crosshair; touch-action: pan-y; }
.timeline-hist { fill: var(--paper-sunken); }
.timeline-baseline { stroke: var(--line-strong); }
.timeline-axis-tick { stroke: var(--line-strong); }
.timeline-axis-label {
  fill: var(--ink-faint);
  font-size: 10px;
  font-family: var(--font-mono);
}
.timeline-shade { fill: rgba(243, 239, 230, 0.7); }
.timeline-window-rect {
  fill: rgba(31, 111, 107, 0.07);
  stroke: var(--accent);
  stroke-width: 1.25;
}
.timeline-hovermark {
  fill: none;
  stroke: var(--ink);
  stroke-width: 1.5;
}
.timeline-selmark line { stroke: var(--accent); stroke-width: 1.25; stroke-dasharray: 3 2; }
.timeline-selmark path { fill: var(--accent); }

.timeline-handles { position: absolute; inset: 34px 0 26px; pointer-events: none; }
.timeline-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 22px;
  margin-left: -11px;
  display: grid;
  place-items: center;
  pointer-events: auto;
  color: var(--accent-ink);
  font-size: 11px;
  cursor: ew-resize;
}
.timeline-handle.is-idle { opacity: 0; }
.timeline-handle.is-idle:focus-visible { opacity: 1; }
.timeline-handle span {
  background: var(--paper-raised);
  border: 1px solid var(--accent);
  border-radius: 5px;
  padding: 3px 2px;
  line-height: 1;
}

/* ————— rail: headline, filters, list ————— */
.headline {
  margin: 12px 12px 0;
  text-align: left;
  border: 1px solid var(--line-strong);
  border-left: 4px solid var(--m-moderate);
  background: var(--paper-raised);
  border-radius: var(--radius);
  padding: 11px 13px;
  font-family: var(--font-display);
  font-size: 14.5px;
  line-height: 1.4;
  cursor: pointer;
  box-shadow: var(--shadow);
}
.headline:hover:not(:disabled) { border-color: var(--ink); }
.headline:disabled { cursor: default; }

.filters { padding: 10px 12px 0; }
.filters-bar {
  display: flex;
  align-items: center;
  gap: 8px;
}
.filters-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--paper-raised);
  padding: 8px 12px;
  min-height: 38px;
  cursor: pointer;
  font-weight: 500;
}
.filters-toggle:hover { border-color: var(--ink); }
.chev { display: inline-block; transition: transform 140ms ease; font-size: 11px; }
.chev.is-open { transform: rotate(90deg); }
.filters-count {
  background: var(--accent);
  color: #fff;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  min-width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  padding: 0 5px;
}
.sort-label { margin-left: auto; }
.select {
  font: inherit;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--paper-raised);
  color: var(--ink);
  padding: 8px 10px;
  min-height: 38px;
  cursor: pointer;
}
.btn-reset {
  border: 0;
  background: none;
  color: var(--danger);
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
  padding: 6px;
  font-size: 12.5px;
}

.filters-body {
  margin-top: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper-raised);
  padding: 4px 12px 12px;
}
.filter-group {
  border: 0;
  padding: 8px 0 0;
  margin: 0;
}
.filter-group legend {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-faint);
  padding: 0;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.chip-row, .mag-stops { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  border: 1px solid var(--line-strong);
  background: var(--paper);
  border-radius: 999px;
  padding: 7px 12px;
  min-height: 34px;
  cursor: pointer;
  font-size: 12.5px;
  color: var(--ink-soft);
}
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip.is-on {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--paper-raised);
  font-weight: 600;
}
.chip-alert-green.is-on { background: var(--alert-green); border-color: var(--alert-green); }
.chip-alert-yellow.is-on { background: var(--alert-yellow); border-color: var(--alert-yellow); }
.chip-alert-orange.is-on { background: var(--alert-orange); border-color: var(--alert-orange); }
.chip-alert-red.is-on { background: var(--alert-red); border-color: var(--alert-red); }

.filter-checks { display: grid; gap: 4px; padding-top: 12px; }
.check {
  display: flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
  padding: 5px 0;
  min-height: 32px;
}
.check input {
  width: 17px; height: 17px;
  accent-color: var(--accent);
  cursor: pointer;
}

.hint {
  position: relative;
  border: 1px solid var(--line-strong);
  background: var(--paper);
  color: var(--ink-faint);
  width: 17px; height: 17px;
  border-radius: 50%;
  font-size: 10.5px;
  line-height: 1;
  cursor: help;
  display: inline-grid;
