import type { Brush, Filters, Quake, SortKey } from "../types";
import { DEFAULT_FILTERS } from "../types";

export type MagBand = "minor" | "light" | "moderate" | "major";

export function magBand(mag: number | null): MagBand {
  if (mag == null || mag < 2.5) return "minor";
  if (mag < 4.5) return "light";
  if (mag < 6) return "moderate";
  return "major";
}

export const MAG_BAND_LABEL: Record<MagBand, string> = {
  minor: "below M 2.5",
  light: "M 2.5–4.4",
  moderate: "M 4.5–5.9",
  major: "M 6.0+",
};

export function formatMag(mag: number | null): string {
  return mag == null ? "—" : mag.toFixed(1);
}

export function depthBandOf(depth: number | null): "shallow" | "intermediate" | "deep" | null {
  if (depth == null) return null;
  if (depth < 70) return "shallow";
  if (depth < 300) return "intermediate";
  return "deep";
}

export const DEPTH_BAND_LABEL = {
  shallow: "Shallow · < 70 km",
  intermediate: "Intermediate · 70–300 km",
  deep: "Deep · > 300 km",
} as const;

export function inBounds(q: Quake, bounds: [number, number, number, number]): boolean {
  const [w, s, e, n] = bounds;
  if (q.lat < s || q.lat > n) return false;
  // Handle viewports that cross the antimeridian or wrap the world.
  if (e - w >= 360) return true;
  const lon = q.lon;
  const wrappedW = ((w + 180) % 360 + 360) % 360 - 180;
  const wrappedE = ((e + 180) % 360 + 360) % 360 - 180;
  const wrappedLon = ((lon + 180) % 360 + 360) % 360 - 180;
  if (wrappedW <= wrappedE) return wrappedLon >= wrappedW && wrappedLon <= wrappedE;
  return wrappedLon >= wrappedW || wrappedLon <= wrappedE;
}

export function matchesFilters(
  q: Quake,
  f: Filters,
  bounds: [number, number, number, number] | null,
): boolean {
  if (f.minMag > 0 && (q.mag == null || q.mag < f.minMag)) return false;
  if (f.depth !== "any" && depthBandOf(q.depth) !== f.depth) return false;
  if (f.alert !== "any" && q.alert !== f.alert) return false;
  if (f.tsunamiOnly && !q.tsunami) return false;
  if (f.status === "reviewed" && q.status !== "reviewed") return false;
  if (f.status === "automatic" && q.status === "reviewed") return false;
  if (f.quakesOnly && q.type !== "earthquake") return false;
  if (f.query) {
    const hay = `${q.place ?? ""} ${q.title}`.toLowerCase();
    if (!hay.includes(f.query.toLowerCase())) return false;
  }
  if (f.inView && bounds && !inBounds(q, bounds)) return false;
  return true;
}

export function applyBrush(quakes: Quake[], brush: Brush): Quake[] {
  if (!brush) return quakes;
  return quakes.filter((q) => q.time >= brush.start && q.time <= brush.end);
}

export function sortQuakes(quakes: Quake[], sort: SortKey): Quake[] {
  const list = [...quakes];
  if (sort === "mag") list.sort((a, b) => (b.mag ?? -10) - (a.mag ?? -10) || b.time - a.time);
  else if (sort === "sig") list.sort((a, b) => (b.sig ?? -1) - (a.sig ?? -1) || b.time - a.time);
  else list.sort((a, b) => b.time - a.time);
  return list;
}

export function countActiveFilters(f: Filters): number {
  let n = 0;
  if (f.minMag !== DEFAULT_FILTERS.minMag) n++;
  if (f.depth !== DEFAULT_FILTERS.depth) n++;
  if (f.alert !== DEFAULT_FILTERS.alert) n++;
  if (f.tsunamiOnly !== DEFAULT_FILTERS.tsunamiOnly) n++;
  if (f.status !== DEFAULT_FILTERS.status) n++;
  if (f.quakesOnly !== DEFAULT_FILTERS.quakesOnly) n++;
  if (f.query !== DEFAULT_FILTERS.query) n++;
  if (f.inView !== DEFAULT_FILTERS.inView) n++;
  return n;
}

export function strongestOf(quakes: Quake[]): Quake | null {
  let best: Quake | null = null;
  for (const q of quakes) {
    if (q.mag == null) continue;
    if (!best || best.mag == null || q.mag > best.mag) best = q;
  }
  return best;
}

const RELATIVE_STEPS: Array<[number, Intl.RelativeTimeFormatUnit]> = [
  [60_000, "second"],
  [3_600_000, "minute"],
  [86_400_000, "hour"],
  [Infinity, "day"],
];

const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

export function relativeTime(ts: number, now: number = Date.now()): string {
  const diff = ts - now;
  const abs = Math.abs(diff);
  for (const [limit, unit] of RELATIVE_STEPS) {
    if (abs < limit) {
      const divisor =
        unit === "second" ? 1_000 : unit === "minute" ? 60_000 : unit === "hour" ? 3_600_000 : 86_400_000;
      return rtf.format(Math.round(diff / divisor), unit);
    }
  }
  return rtf.format(Math.round(diff / 86_400_000), "day");
}

const localZone = Intl.DateTimeFormat().resolvedOptions().timeZone;

export function formatLocal(ts: number): string {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZoneName: "short",
  }).format(ts);
}

export function formatFullLocal(ts: number): string {
  return `${new Intl.DateTimeFormat("en-US", {
    weekday: "short",
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    timeZoneName: "short",
  }).format(ts)} (${localZone})`;
}

export function formatUtc(ts: number): string {
  return `${new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    timeZone: "UTC",
  }).format(ts)} UTC`;
}

export function formatCoords(lat: number, lon: number): string {
  const ns = lat >= 0 ? "N" : "S";
  const ew = lon >= 0 ? "E" : "W";
  return `${Math.abs(lat).toFixed(3)}° ${ns}, ${Math.abs(lon).toFixed(3)}° ${ew}`;
}

// How unusual is this event? Grounded in USGS "sig" (0–~1000, mag/felt/alert composite).
export function significanceNote(q: Quake): { label: string; tone: "calm" | "notable" | "elevated" } {
  const sig = q.sig ?? 0;
  if (q.alert === "red" || q.alert === "orange" || sig >= 900)
    return { label: "High-impact event — see USGS for authoritative updates", tone: "elevated" };
  if (q.alert === "yellow" || sig >= 600 || (q.mag ?? 0) >= 6)
    return { label: "Notable event for this period", tone: "notable" };
  if (sig >= 250 || (q.mag ?? 0) >= 4.5) return { label: "Moderately significant", tone: "notable" };
  return { label: "Ordinary background seismicity", tone: "calm" };
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { Quake } from "../types";
import { formatLocal, formatMag, magBand, relativeTime } from "../lib/quake";

const ROW_HEIGHT = 74;
const OVERSCAN = 6;

type Props = {
  quakes: Quake[];
  selectedId: string | null;
  hoveredId: string | null;
  onSelect: (id: string) => void;
  onHover: (id: string | null) => void;
  now: number;
};

export function EventList({ quakes, selectedId, hoveredId, onSelect, onHover, now }: Props) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewport, setViewport] = useState(480);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setViewport(el.clientHeight));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // Keep the selected event reachable: scroll it into the window when selection
  // changes from the map or timeline.
  useEffect(() => {
    if (!selectedId) return;
    const idx = quakes.findIndex((q) => q.id === selectedId);
    if (idx === -1) return;
    const el = scrollRef.current;
    if (!el) return;
    const top = idx * ROW_HEIGHT;
    if (top < el.scrollTop || top + ROW_HEIGHT > el.scrollTop + el.clientHeight) {
      el.scrollTo({ top: Math.max(0, top - el.clientHeight / 2 + ROW_HEIGHT / 2) });
    }
  }, [selectedId, quakes]);

  // Roving focus: arrows browse (and highlight on the map via onFocus→onHover),
  // Enter/Space on the focused row opens the detail.
  const [focusIdx, setFocusIdx] = useState<number | null>(null);

  useEffect(() => {
    if (focusIdx == null) return;
    const el = scrollRef.current?.querySelector<HTMLButtonElement>(`[data-idx="${focusIdx}"]`);
    el?.focus({ preventScroll: true });
    const scroller = scrollRef.current;
    if (!scroller) return;
    const top = focusIdx * ROW_HEIGHT;
    if (top < scroller.scrollTop) scroller.scrollTo({ top });
    else if (top + ROW_HEIGHT > scroller.scrollTop + scroller.clientHeight)
      scroller.scrollTo({ top: top + ROW_HEIGHT - scroller.clientHeight });
  }, [focusIdx, scrollTop]);

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
      e.preventDefault();
      const current =
        focusIdx ?? (selectedId ? quakes.findIndex((q) => q.id === selectedId) : -1);
      let next = current;
      if (e.key === "ArrowDown") next = Math.min(quakes.length - 1, current + 1);
      else if (e.key === "ArrowUp") next = Math.max(0, current === -1 ? 0 : current - 1);
      else if (e.key === "Home") next = 0;
      else if (e.key === "End") next = quakes.length - 1;
      if (next >= 0 && next < quakes.length) setFocusIdx(next);
    },
    [quakes, selectedId, focusIdx],
  );

  // A new result set invalidates the remembered position.
  useEffect(() => setFocusIdx(null), [quakes]);

  const first = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - OVERSCAN);
  const last = Math.min(quakes.length, Math.ceil((scrollTop + viewport) / ROW_HEIGHT) + OVERSCAN);
  const visible = quakes.slice(first, last);

  return (
    <div
      ref={scrollRef}
      className="event-scroll"
      onScroll={(e) => setScrollTop((e.target as HTMLDivElement).scrollTop)}
      onKeyDown={onKeyDown}
      onMouseLeave={() => onHover(null)}
      tabIndex={0}
      role="group"
      aria-label="Event stream. Press the down arrow to browse events, Enter to open one."
    >
      <ol
        className="event-list"
        aria-label={`Event stream, ${quakes.length} events. Use arrow keys to move between events.`}
        style={{ height: quakes.length * ROW_HEIGHT }}
      >
        {visible.map((q, i) => {
          const idx = first + i;
          const band = magBand(q.mag);
          const isNew = now - q.time < 3_600_000;
          const selected = q.id === selectedId;
          return (
            <li
              key={q.id}
              className="event-item"
              style={{ transform: `translateY(${idx * ROW_HEIGHT}px)` }}
            >
              <button
                type="button"
                data-idx={idx}
                tabIndex={-1}
                className={`event-row ${selected ? "is-selected" : ""} ${q.id === hoveredId ? "is-hovered" : ""}`}
                aria-pressed={selected}
                aria-current={selected ? "true" : undefined}
                onClick={() => onSelect(q.id)}
                onMouseEnter={() => onHover(q.id)}
                onFocus={() => onHover(q.id)}
              >
                <span className={`mag-disc band-${band}`} aria-hidden="true">
                  {formatMag(q.mag)}
                </span>
                <span className="event-main">
                  <span className="event-place">
                    <span className="sr-only">Magnitude {formatMag(q.mag)}, </span>
                    {q.place ?? q.title}
                  </span>
                  <span className="event-meta mono">
                    <span title={formatLocal(q.time)}>{relativeTime(q.time, now)}</span>
                    <span aria-hidden="true"> · </span>
                    <span>{q.depth != null ? `${q.depth.toFixed(0)} km deep` : "depth n/a"}</span>
                  </span>
                </span>
                <span className="event-tags">
                  {isNew && <span className="tag tag-new">new</span>}
                  {q.tsunami && <span className="tag tag-tsunami">tsunami info</span>}
                  {q.alert && <span className={`tag tag-alert-${q.alert}`}>{q.alert} alert</span>}
                  {q.type !== "earthquake" && <span className="tag">{q.type.replace(/_/g, " ")}</span>}
                </span>
              </button>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

